import javax.swing.JSlider;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

/**
 * TASK: Keep two bounded components in step.
 *
 * The panel owns a JSlider named "slider" running 0..100 and a JSpinner named
 * "spinner" whose SpinnerNumberModel runs 0..100 in steps of 5. Implement:
 *
 *   setValue(int v)   -- CLAMP v into the slider's [getMinimum(), getMaximum()]
 *                        range, then push the clamped number into BOTH
 *                        components
 *   getValue()        -- the slider's current value
 *   spinnerValue()    -- the spinner's value as an int
 *   stepUp()          -- move up by the spinner model's step size, clamped
 *
 * The edge case that matters: SpinnerNumberModel THROWS
 * IllegalArgumentException if you hand it a value outside its range, so
 * setValue must clamp BEFORE calling spinner.setValue. A JSlider would have
 * clamped silently, which is exactly why the two disagree if you forget.
 *
 * Useful calls: slider.getMinimum(), slider.getMaximum(), slider.setValue(int),
 * spinner.setValue(Integer), ((Number) spinner.getValue()).intValue(),
 * ((SpinnerNumberModel) spinner.getModel()).getStepSize().intValue().
 *
 * Example:
 *   panel.setValue(120);  -> both read 100
 *   panel.setValue(-5);   -> both read 0
 *   panel.stepUp();       -> both read 5
 *
 * No window is ever opened -- the tests read the components directly.
 */
public class RangePickerPanel extends JPanel {

    private final JSlider slider = new JSlider(0, 100, 50);
    private final JSpinner spinner = new JSpinner(new SpinnerNumberModel(50, 0, 100, 5));

