import javax.swing.JSlider;
import javax.swing.JSpinner;

public class RangePickerPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        for (java.awt.Component c : root.getComponents()) {
            if (name.equals(c.getName())) {
                return c;
            }
            if (c instanceof java.awt.Container) {
                java.awt.Component found = find((java.awt.Container) c, name);
                if (found != null) {
                    return found;
                }
            }
        }
        return null;
    }

    static String both(RangePickerPanel panel) {
        try {
            return panel.getValue() + "/" + panel.spinnerValue();
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
    }

    static String act(RangePickerPanel panel, int v) {
        try {
            panel.setValue(v);
        } catch (Throwable t) {
            return "threw " + t.getClass().getSimpleName();
        }
        return both(panel);
    }

    public static void main(String[] args) {
        try {
            RangePickerPanel panel = new RangePickerPanel();
            java.awt.Component s = find(panel, "slider");
            java.awt.Component p = find(panel, "spinner");

            check("both named components exist", true,
                    s instanceof JSlider && p instanceof JSpinner);
            check("the starting value", "50/50", both(panel));
            check("an ordinary value reaches both and the real slider", "75/75/75",
                    act(panel, 75) + "/" + (s instanceof JSlider ? ((JSlider) s).getValue() : "?"));
            check("a value above the maximum is clamped", "100/100", act(panel, 120));
            check("a value below the minimum is clamped", "0/0", act(panel, -5));

            panel.stepUp();
            check("one step up from the minimum", "5/5", both(panel));

            panel.stepUp();
            panel.stepUp();
            panel.stepUp();
            check("three more steps", "20/20", both(panel));

            panel.setValue(98);
            panel.stepUp();
            check("a step that would overshoot is clamped", "100/100", both(panel));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected " + t.getClass().getSimpleName() + ": " + t.getMessage());
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

