import javax.swing.JPanel;
import javax.swing.JSlider;
import javax.swing.JSpinner;
import javax.swing.SpinnerNumberModel;

public class RangePickerPanel extends JPanel {

    private final JSlider slider = new JSlider(0, 100, 50);
    private final JSpinner spinner = new JSpinner(new SpinnerNumberModel(50, 0, 100, 5));

    public RangePickerPanel() {
        slider.setName("slider");
        spinner.setName("spinner");
        add(slider);
        add(spinner);
    }

    public void setValue(int v) {
        int clamped = v;
        if (clamped < slider.getMinimum()) {
            clamped = slider.getMinimum();
        }
        if (clamped > slider.getMaximum()) {
            clamped = slider.getMaximum();
        }
        slider.setValue(clamped);
        spinner.setValue(Integer.valueOf(clamped));
    }

    public int getValue() {
        return slider.getValue();
    }

    public int spinnerValue() {
        return ((Number) spinner.getValue()).intValue();
    }

    public void stepUp() {
        int step = ((SpinnerNumberModel) spinner.getModel()).getStepSize().intValue();
        setValue(getValue() + step);
    }
}
